      if (!Town.autoRevive() && Hunt.cfg().onDeath === 'stop') {
        this.message = 'Auto-start: the character is dead and On death is set to Stop, so the bot was not started.';
        Log.info(this.message); UI.toast(this.message, 'warn', 6000);
        return;
      }
